import java.util.*;
import java.lang.Math;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] input = parseInput(sc, Integer::parseInt);
        int n = input[0];
        int mod = input[1];

        List<Long> sequence = new ArrayList<>();
        sequence.add(0L);
        sequence.add(1L);
        long total_value = 1L;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            long current_sum = total_value;

            for (int f = 2; f < limit; f++) {
                current_sum = addModulo(current_sum, sequence.get(i / f), mod);
            }

            int boundary = i;
            for (int j = 1; j <= i / limit; j++) {
                int next_idx = i / (j + 1);
                current_sum = addModulo(current_sum, multiplyModulo(boundary - next_idx, sequence.get(j), mod), mod);
                boundary = next_idx;
            }

            total_value = addModulo(total_value, current_sum, mod);
            sequence.add(current_sum);
        }

        System.out.println(sequence.get(sequence.size() - 1));
        sc.close();
    }

    private static int[] parseInput(Scanner sc, java.util.function.Function<String, Integer> typeFunc) {
        String[] parts = sc.nextLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = typeFunc.apply(parts[i]);
        }
        return result;
    }

    private static long addModulo(long a, long b, int mod) {
        return ((a + b) % mod + mod) % mod;
    }

    private static long multiplyModulo(long a, long b, int mod) {
        return ((a * b) % mod + mod) % mod;
    }
}
